def _actors_add_component(*, class_, target, attach_to=None, location=None, name=None, properties=None):
    """Adds any engine component to an actor and sets its properties: movement (ProjectileMovementComponent, RotatingMovementComponent, InterpToMovementComponent), shapes and triggers (SphereComponent, BoxComponent, CapsuleComponent), lights (PointLightComponent, SpotLightComponent), AudioComponent, PhysicsConstraintComponent, PhysicsThrusterComponent, RadialForceComponent... Scene components attach to the root (or attach_to) at location. Change it later with reflection.set_properties / call_function on the returned ref.
    Returns: The new component. Fails if the class is unknown, abstract or not a component, or a property does not apply.

    Args:
        class_ (str): Required. Component class name, e.g. "RotatingMovementComponent" (the U prefix is optional).
        target (str): Required. Actor or node id, e.g. "n12". (Reference to Actor: node id (n12), node path, actor:Name
            or object path)
        attach_to (str): Name of the scene component to attach to (default: the root). Default "".
        location (list[float]): Relative location of a scene component. ([x, y, z] (cm))
        name (str): Component name (default: generated).
        properties (any): Property values, e.g. {"RotationRate": {"Yaw": 90}} or {"InitialSpeed": 1200,
            "ProjectileGravityScale": 0}. (Any JSON value)
    """
    args = {}
    if class_ is not None:
        args['class'] = class_
    if target is not None:
        args['target'] = target
    if attach_to is not None:
        args['attach_to'] = attach_to
    if location is not None:
        args['location'] = location
    if name is not None:
        args['name'] = name
    if properties is not None:
        args['properties'] = properties
    return call('actors.add_component', **args)


def _actors_attach(*, child, keep_world=None, parent=None, socket=None):
    """Attaches an actor to another actor, or detaches it when parent is omitted. Undoable. For tool-created nodes this also moves the node in the scene graph. Fails if the parent is the child or attached below it.
    Returns: Child and new parent references.

    Args:
        child (str): Required. Actor to attach. (Reference to Actor: node id (n12), node path, actor:Name or object
            path)
        keep_world (bool): Keep the world transform (false keeps the relative transform). Default true.
        parent (str): New parent actor; omit (or "") to detach. (Reference to Actor: node id (n12), node path,
            actor:Name or object path)
        socket (str): Socket or bone name on the parent's root component, e.g. "hand_r". Default "".
    """
    args = {}
    if child is not None:
        args['child'] = child
    if keep_world is not None:
        args['keep_world'] = keep_world
    if parent is not None:
        args['parent'] = parent
    if socket is not None:
        args['socket'] = socket
    return call('actors.attach', **args)


