def _ai_build_navigation(*, bounds=None, margin=None, timeout_seconds=None):
    """Builds a navmesh over an area so agents can find paths, and waits until it is ready. Call it after the walkable geometry exists; it updates by itself when things move later (dynamic generation).
    Returns: Navigation status (navmesh present, building, bounds, a hint if something is missing).

    Args:
        bounds (dict): Area {min:[x,y,z], max:[x,y,z]} in cm; default: everything in the scene plus a margin.
        margin (float): Extra space around the automatic bounds (cm). Default 1000.
        timeout_seconds (float): Give up waiting after this long. Default 60.
    """
    args = {}
    if bounds is not None:
        args['bounds'] = bounds
    if margin is not None:
        args['margin'] = margin
    if timeout_seconds is not None:
        args['timeout_seconds'] = timeout_seconds
    return call('ai.build_navigation', **args)


