def _gas_define_effect(*, duration_policy, name, application_required_tags=None, cues=None, duration=None, granted_tags=None, modifiers=None, period=None, replace=None, stack_limit=None, stacking=None):
    """Defines a gameplay effect at runtime (a transient GameplayEffect; no asset needed), stored by name for gas.apply_effect and gas.give_ability. Typical uses: damage (instant, Damage +N), heal (instant, Health +N), poison (has_duration 5 s, period 1, Damage +4), speed buff (has_duration 10 s, Speed multiply 1.5, granted tag), stun (has_duration 2 s, granted tag State.Stunned).
    Returns: The stored definition. Fails on unknown attributes or tags (with candidates), an existing name without replace, or a has_duration effect without a positive duration.

    Args:
        duration_policy ('Instant' | 'HasDuration' | 'Infinite'): Required. instant, has_duration or infinite.
        name (str): Required. Effect name, e.g. "Poison".
        application_required_tags (list[str]): Tags the target must own for the effect to apply.
        cues (list[str]): Gameplay cue tags to trigger (GameplayCue.*).
        duration (float): Seconds, for has_duration (e.g. 5). Default 0.
        granted_tags (list[str]): Tags the target owns while the effect is active (duration/infinite only), e.g.
            ["Gas.State.Dead"].
        modifiers (list[dict]): Attribute changes, e.g. [{"attribute":"Damage","op":"add","magnitude":4}] or
            [{"attribute":"Damage","set_by_caller":"Gas.SetByCaller.Magnitude"}].
        period (float): Seconds between executions for periodic effects (0 = not periodic), e.g. 1. Default 0.
        replace (bool): Replace an existing definition with the same name (effects already active keep the old one).
            Default false.
        stack_limit (int): Maximum stacks when stacking (0 = unlimited). Default 0.
        stacking ('None' | 'AggregateBySource' | 'AggregateByTarget'): none (each application separate),
            aggregate_by_source or aggregate_by_target. Default "None".
    """
    args = {}
    if duration_policy is not None:
        args['duration_policy'] = duration_policy
    if name is not None:
        args['name'] = name
    if application_required_tags is not None:
        args['application_required_tags'] = application_required_tags
    if cues is not None:
        args['cues'] = cues
    if duration is not None:
        args['duration'] = duration
    if granted_tags is not None:
        args['granted_tags'] = granted_tags
    if modifiers is not None:
        args['modifiers'] = modifiers
    if period is not None:
        args['period'] = period
    if replace is not None:
        args['replace'] = replace
    if stack_limit is not None:
        args['stack_limit'] = stack_limit
    if stacking is not None:
        args['stacking'] = stacking
    return call('gas.define_effect', **args)


