# ------------------------------------------------------------------ history

def _history_undo(*, count=None, to_checkpoint=None):
    """Undo the last N changes, or back to a checkpoint.

    Args:
        count (int): Changes to undo Default 1.
        to_checkpoint (str): Undo until this checkpoint
    """
    args = {}
    if count is not None:
        args['count'] = count
    if to_checkpoint is not None:
        args['to_checkpoint'] = to_checkpoint
    return call('history.undo', **args)


def _history_redo(*, count=None):
    """Redo the last N undone changes.

    Args:
        count (int): Changes to redo Default 1.
    """
    args = {}
    if count is not None:
        args['count'] = count
    return call('history.redo', **args)


def _history_get_history(*, include_redo=None, limit=None):
    """Undo stack (newest first), redo count, open transaction.

    Args:
        include_redo (bool): Also list redo entries Default false.
        limit (int): Max results (default 25)
    """
    args = {}
    if include_redo is not None:
        args['include_redo'] = include_redo
    if limit is not None:
        args['limit'] = limit
    return call('history.get_history', **args)


def _history_begin_transaction(*, label=None):
    """Group following changes into one undo step. Nests.

    Args:
        label (str): Label shown in history
    """
    args = {}
    if label is not None:
        args['label'] = label
    return call('history.begin_transaction', **args)


def _history_end_transaction(*, commit=None):
    """Close the transaction: commit as one step, or roll back its changes.

    Args:
        commit (bool): false = undo everything in it Default true.
    """
    args = {}
    if commit is not None:
        args['commit'] = commit
    return call('history.end_transaction', **args)


def _history_checkpoint(*, name):
    """Name the current state so rollback can return to it.

    Args:
        name (str): Required. Checkpoint name
    """
    args = {}
    if name is not None:
        args['name'] = name
    return call('history.checkpoint', **args)


def _history_rollback(*, name):
    """Undo everything after a checkpoint.

    Args:
        name (str): Required. Checkpoint name
    """
    args = {}
    if name is not None:
        args['name'] = name
    return call('history.rollback', **args)


def _history_set_history_limit(*, limit):
    """Max undo entries for this session. Oldest entries become permanent.

    Args:
        limit (int): Required. Max entries
    """
    args = {}
    if limit is not None:
        args['limit'] = limit
    return call('history.set_history_limit', **args)


history = SimpleNamespace(undo=_history_undo, redo=_history_redo, get_history=_history_get_history, begin_transaction=_history_begin_transaction, end_transaction=_history_end_transaction, checkpoint=_history_checkpoint, rollback=_history_rollback, set_history_limit=_history_set_history_limit)
history.__doc__ = 'Undo/redo, transactions, checkpoints and rollback (per session)'


