# ------------------------------------------------------------------ log

def _log_get_stat(*, names=None):
    """Reads frame and memory stats. Fails for unknown stat names.
    Returns: Stat name -> value.

    Args:
        names (list[str]): Stats to read: fps, frame_ms, game_ms, render_ms, rhi_ms, gpu_ms, memory_mb, actors, nodes
            (default: fps, frame_ms, game_ms, render_ms, gpu_ms, memory_mb).
    """
    args = {}
    if names is not None:
        args['names'] = names
    return call('log.get_stat', **args)


def _log_subscribe_log_category(*, category, enabled=None, min_verbosity=None):
    """Pushes new lines of a log category to this session as events (type "log"), or stops doing so.
    Returns: The session's subscriptions and how lines are delivered.

    Args:
        category (str): Required. Log category, e.g. "LogBlueprintUserMessages".
        enabled (bool): False to unsubscribe. Default true.
        min_verbosity ('Fatal' | 'Error' | 'Warning' | 'Display' | 'Log' | 'Verbose' | 'VeryVerbose'): Most verbose
            level to push. Default "Log".
    """
    args = {}
    if category is not None:
        args['category'] = category
    if enabled is not None:
        args['enabled'] = enabled
    if min_verbosity is not None:
        args['min_verbosity'] = min_verbosity
    return call('log.subscribe_log_category', **args)


def _log_tail_log(*, category=None, contains=None, limit=None, min_verbosity=None, since_seq=None):
    """Returns recent log lines, oldest first, filtered by category, verbosity and text.
    Returns: The lines {seq, category, verbosity, message} and last_seq.

    Args:
        category (str): Log category, e.g. "LogTemp". Default "".
        contains (str): Substring the message must contain. Default "".
        limit (int): Maximum lines returned (0 = project default); the newest matching lines are kept. Default 25.
        min_verbosity ('Fatal' | 'Error' | 'Warning' | 'Display' | 'Log' | 'Verbose' | 'VeryVerbose'): Most verbose
            level to include: Error shows only errors (and fatal), Log includes Display and Log. Default "Log".
        since_seq (int): Only lines after this sequence number (the last_seq of a previous call). Default 0.
    """
    args = {}
    if category is not None:
        args['category'] = category
    if contains is not None:
        args['contains'] = contains
    if limit is not None:
        args['limit'] = limit
    if min_verbosity is not None:
        args['min_verbosity'] = min_verbosity
    if since_seq is not None:
        args['since_seq'] = since_seq
    return call('log.tail_log', **args)


log = SimpleNamespace(get_stat=_log_get_stat, subscribe_log_category=_log_subscribe_log_category, tail_log=_log_tail_log)
log.__doc__ = 'Log and stats: read the game log, subscribe to log categories as pushed events, and read frame/memory stats.'


