def _pcg_scatter(*, items, spline, exclude=None, ground=None, jitter=None, keep=None, min_distance=None, mode=None, name=None, noise_scale=None, offset=None, seed=None, side=None, spacing=None, surface=None):
    """Scatters copies of builder objects along a spline (both sides of a road, a fence line) or inside a closed spline (a forest, a field) with a PCG graph (spline or surface sampler, jitter, self pruning), then noise thinning, exclusion zones and ground snapping. Rendered as GPU instances (thousands are cheap). Undoable; same seed, same result.

    Args:
        items (list[dict]): Required. What to place: {template, weight, scale:[min,max], align, random_yaw, z_offset,
            collision}.
        spline (str): Required. Spline node (spline.create_spline). (Reference to Actor: node id (n12), node path,
            actor:Name or object path)
        exclude (list[dict]): Keep clear of these splines: {spline, clearance}: a band of clearance cm either side; a
            closed spline also keeps its whole inside clear (clearings, fields, plazas).
        ground (bool): Snap to the ground below. Default true.
        jitter (float): Random position offset in cm (-1 = 35% of spacing). Default -1.
        keep (float): Share of points kept, clumped by noise (1 = all). Default 1.
        min_distance (float): Minimum gap between objects in cm (-1 = 60% of spacing). Default -1.
        mode ('Along' | 'Inside'): along: on or beside the spline; inside: fill a closed spline. Default "Along".
        name (str): Node name. Default "Scatter".
        noise_scale (float): Clump size for keep, in cm. Default 3000.
        offset (list[float]): along: lateral band [min,max] in cm from the spline (e.g. [500,1200] keeps trees off a
            road); [0,0] = on the line. ([x, y])
        seed (int): Random seed. Default 1.
        side ('Both' | 'Left' | 'Right'): along with an offset: which side of the spline. Default "Both".
        spacing (float): Sample spacing in cm. Default 400.
        surface (str): Only place where this node (e.g. the terrain) is the first thing below the point: spots covered
            by a building, road, wall or roof are dropped instead of being planted on top of it. Implies ground
            snapping. (Reference to Actor: node id (n12), node path, actor:Name or object path)
    """
    args = {}
    if items is not None:
        args['items'] = items
    if spline is not None:
        args['spline'] = spline
    if exclude is not None:
        args['exclude'] = exclude
    if ground is not None:
        args['ground'] = ground
    if jitter is not None:
        args['jitter'] = jitter
    if keep is not None:
        args['keep'] = keep
    if min_distance is not None:
        args['min_distance'] = min_distance
    if mode is not None:
        args['mode'] = mode
    if name is not None:
        args['name'] = name
    if noise_scale is not None:
        args['noise_scale'] = noise_scale
    if offset is not None:
        args['offset'] = offset
    if seed is not None:
        args['seed'] = seed
    if side is not None:
        args['side'] = side
    if spacing is not None:
        args['spacing'] = spacing
    if surface is not None:
        args['surface'] = surface
    return call('pcg.scatter', **args)


