def _physics_add_impulse(*, impulse, target, at=None, velocity_change=None):
    """Pushes a simulating object. Not undoable (the motion that follows cannot be reverted).
    Returns: The pushed actor and its velocity right after the push. Fails if the target is not simulating physics (call set_simulate first).
    This cannot be undone: only call it after explicit direction or permission from the user.

    Args:
        impulse (list[float]): Required. [x,y,z]; a velocity change in cm/s with velocity_change, else an impulse in
            kg*cm/s, e.g. [0,0,500]. ([x, y, z] (cm))
        target (str): Required. Simulating actor or "actor#Component", e.g. "n12". (Reference to PrimitiveComponent:
            node id (n12), node path, actor:Name or object path)
        at (list[float]): Apply at this world point [x,y,z] (adds spin); default the centre of mass. ([x, y, z] (cm))
        velocity_change (bool): Treat impulse as a velocity change (ignores mass). Default true.
    """
    args = {}
    if impulse is not None:
        args['impulse'] = impulse
    if target is not None:
        args['target'] = target
    if at is not None:
        args['at'] = at
    if velocity_change is not None:
        args['velocity_change'] = velocity_change
    return call('physics.add_impulse', **args)


