def _physics_line_trace(*, start, channel=None, complex=None, direction=None, distance=None, end=None, ignore=None, limit=None, multi=None):
    """Traces a ray through the world and returns what it hits.
    Returns: {hit, hits:[{actor, component, location, normal, distance}]} nearest first. Fails if neither end nor a non-zero direction is given, or the channel name is unknown (the channels are listed).

    Args:
        start (list[float]): Required. Ray start [x,y,z] in cm, e.g. [0,0,500]. ([x, y, z] (cm))
        channel (str): Trace channel or object type name from get_collision_channels, e.g. "Visibility", "Camera",
            "WorldStatic", "Pawn". Default "Visibility".
        complex (bool): Trace per-triangle collision instead of simple shapes. Default false.
        direction (list[float]): Ray direction, e.g. [0,0,-1] (used when end is omitted). ([x, y, z] (cm))
        distance (float): Ray length in cm when using direction. Default 100000.
        end (list[float]): Ray end [x,y,z]; or give direction (+ distance) instead. ([x, y, z] (cm))
        ignore (list[str]): Actors the ray passes through (node ids, paths, actor:Name).
        limit (int): Maximum hits with multi (0 = default list limit). Default 0.
        multi (bool): Return every hit along the ray instead of the first blocking one. Default false.
    """
    args = {}
    if start is not None:
        args['start'] = start
    if channel is not None:
        args['channel'] = channel
    if complex is not None:
        args['complex'] = complex
    if direction is not None:
        args['direction'] = direction
    if distance is not None:
        args['distance'] = distance
    if end is not None:
        args['end'] = end
    if ignore is not None:
        args['ignore'] = ignore
    if limit is not None:
        args['limit'] = limit
    if multi is not None:
        args['multi'] = multi
    return call('physics.line_trace', **args)


