def _physics_set_body(*, target, angular_damping=None, continuous_collision=None, friction=None, gravity=None, linear_damping=None, lock_rotation=None, lock_translation=None, mass_kg=None, restitution=None):
    """Tunes how a body behaves: weight, grip, bounce, drag, gravity and axis locks. Only the settings you pass change. Works before or after set_simulate. Examples: a rolling barrel {friction:0.2, restitution:0.1, lock_translation:["y"]}; a bouncy ball {restitution:0.9}; a 2D game keeps bodies in the X/Z plane with lock_translation:["y"], lock_rotation:["x","z"].
    Returns: The body state. Fails if the target has no collision or a lock axis is not x, y or z.

    Args:
        target (str): Required. Actor or "actor#Component", e.g. "n12". (Reference to PrimitiveComponent: node id (n12),
            node path, actor:Name or object path)
        angular_damping (float): Drag on spin.
        continuous_collision (bool): CCD for fast objects that must not pass through thin walls.
        friction (float): 0 (ice) .. 1+ (rubber).
        gravity (bool): Whether gravity pulls it.
        linear_damping (float): Drag on movement (0 none, 1-5 heavy).
        lock_rotation (list[str]): Axes it cannot rotate around, e.g. ["x","z"] (only spins around y).
        lock_translation (list[str]): World axes it cannot move along, e.g. ["y"].
        mass_kg (float): Mass override in kg.
        restitution (float): Bounciness 0 .. 1.
    """
    args = {}
    if target is not None:
        args['target'] = target
    if angular_damping is not None:
        args['angular_damping'] = angular_damping
    if continuous_collision is not None:
        args['continuous_collision'] = continuous_collision
    if friction is not None:
        args['friction'] = friction
    if gravity is not None:
        args['gravity'] = gravity
    if linear_damping is not None:
        args['linear_damping'] = linear_damping
    if lock_rotation is not None:
        args['lock_rotation'] = lock_rotation
    if lock_translation is not None:
        args['lock_translation'] = lock_translation
    if mass_kg is not None:
        args['mass_kg'] = mass_kg
    if restitution is not None:
        args['restitution'] = restitution
    return call('physics.set_body', **args)


def _physics_set_simulate(*, target, enabled=None):
    """Turns physics simulation on or off. A Static or Stationary component is switched to Movable first (reported in the result). Undoable: undo stops simulating and puts the object back where it was (re-attached).
    Returns: {target, simulating, mobility_changed, note}. Fails if the component has no collision (physics cannot simulate without it).

    Args:
        target (str): Required. Actor or "actor#Component", e.g. "n12". (Reference to PrimitiveComponent: node id (n12),
            node path, actor:Name or object path)
        enabled (bool): true to simulate, false to stop. Default true.
    """
    args = {}
    if target is not None:
        args['target'] = target
    if enabled is not None:
        args['enabled'] = enabled
    return call('physics.set_simulate', **args)


