def _reflection_call_function(*, function, target, args=None):
    """Calls a BlueprintCallable function with named arguments. Missing arguments use zero/default values (listed in defaulted); a WorldContextObject argument is filled in. Fails for unknown functions, unknown argument names, latent functions and functions denied by project settings.
    Returns: Return value, out parameters, defaulted parameter names and whether the call was side-effect free.
    This cannot be undone: only call it after explicit direction or permission from the user.

    Args:
        function (str): Required. Function name, e.g. "K2_GetActorLocation" (see list_functions).
        target (str): Required. Object, or class:/Script/Module.Class for static library functions. (Reference to
            Object: node id (n12), node path, actor:Name or object path)
        args (any): Arguments by parameter name, e.g. {"NewLocation": [0, 0, 100]}. (Any JSON value)
    """
    args = {}
    if function is not None:
        args['function'] = function
    if target is not None:
        args['target'] = target
    if args is not None:
        args['args'] = args
    return call('reflection.call_function', **args)


