def _spline_create_spline(*, points, closed=None, follow_ground=None, linear=None, name=None, parent=None, profile=None):
    """Creates a spline through world points, optionally shown as a mesh swept along it. Undoable.
    Returns: The spline node, its length and whether it is closed.

    Args:
        points (list[list[float]]): Required. World positions [x,y,z] in cm, at least 2 (e.g.
            [[0,0,0],[5000,2000,0],[9000,0,0]]).
        closed (bool): Closed loop: an area (forest, field, lake shore) instead of a path. Default false.
        follow_ground (bool): Drop each point onto the ground below before building the curve. Default false.
        linear (bool): Straight segments between points instead of a smooth curve (fences, walls, buildings). Default
            false.
        name (str): Node name. Default "Spline".
        parent (str): Optional parent node. (Reference to Actor: node id (n12), node path, actor:Name or object path)
        profile (dict): Mesh along the spline: {kind: ribbon|wall|tube|none, width, height, step, z_offset,
            material:{...}}.
    """
    args = {}
    if points is not None:
        args['points'] = points
    if closed is not None:
        args['closed'] = closed
    if follow_ground is not None:
        args['follow_ground'] = follow_ground
    if linear is not None:
        args['linear'] = linear
    if name is not None:
        args['name'] = name
    if parent is not None:
        args['parent'] = parent
    if profile is not None:
        args['profile'] = profile
    return call('spline.create_spline', **args)


