def _style_apply(*, lighting=None, lighting_enabled=None, material=None, post=None, preset=None, settings=None):
    """Restyles the whole scene: a preset and/or overrides of any layer, merged key by key. Without a preset, overrides tweak the style already applied. The material/post layer is one undo step; the lighting layer adds lighting undo steps.
    Returns: The applied style and any lighting notes. Fails if the preset is unknown (the hint lists the presets) or the style assets are missing.

    Args:
        lighting (any): {mood, sun:{rotation, intensity, temperature, color}, sky:{intensity, color}, fog:{density,
            color, height_falloff}}. (Any JSON value)
        lighting_enabled (bool): Also change the lighting. Default true.
        material (any): {Weathering 0-1 scene-wide dirt, rain streaks and dust (realistic 0.2-0.4, default 0.25),
            Faceted 0-1 flat shading, Pattern 0-1 procedural detail, Steps colour palette steps (0 off), Saturation,
            RimStrength, RimColor, Tint}, e.g. {"Saturation": 1.2}. (Any JSON value)
        post (any): {Toon 0-1, Bands, ShadowFloor, Outline 0-1, OutlineWidth px, OutlineColor, DepthSens, NormalSens,
            Paint 0-1, PaintRadius, PaintScale, PixelSize px, Levels, Saturation, Contrast, Tint}, e.g. {"Outline":
            0.6}. (Any JSON value)
        preset (str): Preset name, e.g. "toon"; empty = tweak the current style. Default "".
        settings (any): {bloom, vignette, ao, grain, chromatic, exposure_bias, temperature}. (Any JSON value)
    """
    args = {}
    if lighting is not None:
        args['lighting'] = lighting
    if lighting_enabled is not None:
        args['lighting_enabled'] = lighting_enabled
    if material is not None:
        args['material'] = material
    if post is not None:
        args['post'] = post
    if preset is not None:
        args['preset'] = preset
    if settings is not None:
        args['settings'] = settings
    return call('style.apply', **args)


def _style_define_preset(*, name, based_on=None, description=None, lighting=None, material=None, post=None, settings=None):
    """Adds or replaces a named style preset, optionally starting from another preset. Lasts until the game restarts (put permanent presets in Config/RuntimeToolsets/StylePresets.json).
    Returns: The new preset. Fails if the name is empty or based_on is not a preset.

    Args:
        name (str): Required. Preset name, e.g. "comic".
        based_on (str): Start from this preset, e.g. "toon". Default "".
        description (str): What it looks like. Default "Custom style".
        lighting (any): Lighting overrides. (Any JSON value)
        material (any): Material layer overrides. (Any JSON value)
        post (any): Post layer overrides, e.g. {"OutlineWidth": 3}. (Any JSON value)
        settings (any): Post settings overrides. (Any JSON value)
    """
    args = {}
    if name is not None:
        args['name'] = name
    if based_on is not None:
        args['based_on'] = based_on
    if description is not None:
        args['description'] = description
    if lighting is not None:
        args['lighting'] = lighting
    if material is not None:
        args['material'] = material
    if post is not None:
        args['post'] = post
    if settings is not None:
        args['settings'] = settings
    return call('style.define_preset', **args)


def _style_get():
    """The style currently applied.
    Returns: applied = false (and a note in style) when no style was applied, otherwise the style object.
    """
    args = {}
    return call('style.get', **args)


def _style_list_presets():
    """Lists the art style presets with descriptions, and every adjustable parameter per layer.
    Returns: Presets sorted by name, and the layer parameter list.
    """
    args = {}
    return call('style.list_presets', **args)


